(result, exception) -> {
              if (Objects.isNull(exception)) {
                LogUtils.setCorrelationId(correlationId);
                log.info(
                    MessageFormat.format(
                        "Message was sent to internal topic. Event type: {0}, external event id: {1}",
                        event.getPayload().getType(), event.getPayload().getId()));
              } else {
                LogUtils.setCorrelationId(correlationId);
                log.error(
                    MessageFormat.format(
                        "Failed to send message to internal topic. Event type: {0}, external event id: {1}",
                        event.getPayload().getType(), event.getPayload().getId()),
                    exception);
              }
            }

(result, throwable) -> {
              Duration duration = Duration.between(start, Instant.now());
              if (throwable == null) {
                onSuccess(messageKey, duration);
              } else {
                onFailure(messageKey, throwable, duration);
              }
            }

psp -> {
              @SuppressWarnings("unchecked")
              LinkedHashMap<String, String> ipAddresses =
                  pspSettings.get(psp, "ip-addresses", LinkedHashMap.class);
              ipAddresses
                  .values()
                  .forEach(ipAddress -> ipAddressMatchers.add(new IpAddressMatcher(ipAddress)));
            }

stripeObject -> {
              log.info("Using Stripe object for payload");
              return stripeObject.toJson();
            }

() -> {
              log.info("Using Raw Json for payload");
              return event.getDataObjectDeserializer().getRawJson();
            }
